export const tokensCSS = "/* tokens:begin — manta-tokens 가 생성한다. 직접 고치지 말 것. */\n/* manta-tokens — scripts/build.mjs 가 tokens.json 에서 생성한다. 직접 고치지 말 것. */\n\n:root,\n.manta-tokens {\n  --manta-bg: var(--background-primary, #ffffff);\n  --manta-surface: var(--background-secondary, #f4f6f8);\n  --manta-surface-raised: var(--background-secondary-alt, #eceff3);\n  --manta-border: var(--background-modifier-border, #c9cfd6);\n  --manta-border-strong: var(--background-modifier-border-hover, #8a929d);\n  --manta-divider: var(--divider-color, #e3e6ea);\n  --manta-text: var(--text-normal, #1f2328);\n  --manta-text-muted: var(--text-muted, #4b5563);\n  --manta-text-faint: var(--text-faint, #8a929d);\n  --manta-accent: var(--interactive-accent, #2b96ed);\n  --manta-accent-text: var(--text-on-accent, #ffffff);\n  --manta-key-bg: #1f2328;\n  --manta-key-text: #ffffff;\n  --manta-out-bg: #eaf3fc;\n  --manta-out-border: #9cc3e6;\n  --manta-series-1: #42764c;\n  --manta-series-2: #356eaa;\n  --manta-series-3: #896a28;\n  --manta-series-4: #81558d;\n  --manta-error: var(--text-error, #b42318);\n  --manta-warning: var(--text-warning, #b7791f);\n  --manta-success: var(--text-success, #176b35);\n\n  --manta-radius-xs: 3px;\n  --manta-radius-sm: var(--radius-s, 5px);\n  --manta-radius-md: var(--radius-m, 8px);\n  --manta-space-1: var(--size-4-1, 4px);\n  --manta-space-2: var(--size-4-2, 8px);\n  --manta-space-3: var(--size-4-3, 12px);\n  --manta-space-4: var(--size-4-4, 16px);\n  --manta-line-thin: 1px;\n  --manta-line-base: 1.2px;\n  --manta-font-sans: var(--font-text, \"Pretendard Variable\", Pretendard, \"Apple SD Gothic Neo\", \"Noto Sans KR\", system-ui, sans-serif);\n  --manta-font-ui: var(--font-interface, \"Pretendard Variable\", Pretendard, \"Apple SD Gothic Neo\", \"Noto Sans KR\", system-ui, sans-serif);\n  --manta-font-mono: var(--font-monospace, \"JetBrains Mono Variable\", ui-monospace, SFMono-Regular, Menlo, monospace);\n  --manta-size-xs: var(--font-ui-smaller, 11px);\n  --manta-size-sm: var(--font-ui-small, 12px);\n  --manta-size-md: var(--font-ui-medium, 13px);\n  --manta-size-lg: var(--font-ui-large, 15px);\n  --manta-size-xl: 18px;\n  --manta-control-height: var(--input-height, 30px);\n  --manta-control-focus-width: var(--focus-ring-width, 2px);\n  --manta-control-icon: var(--icon-size, 16px);\n}\n\n/* 다크: Obsidian 은 .theme-dark, 그 밖의 호스트는 prefers-color-scheme 으로 뒤집는다. */\n.theme-dark,\n[data-theme=\"dark\"] {\n  --manta-bg: var(--background-primary, #0d1117);\n  --manta-surface: var(--background-secondary, #161b22);\n  --manta-surface-raised: var(--background-secondary-alt, #1c2430);\n  --manta-border: var(--background-modifier-border, #3d4754);\n  --manta-border-strong: var(--background-modifier-border-hover, #738091);\n  --manta-divider: var(--divider-color, #2a323d);\n  --manta-text: var(--text-normal, #e6edf3);\n  --manta-text-muted: var(--text-muted, #a4afbc);\n  --manta-text-faint: var(--text-faint, #738091);\n  --manta-accent: var(--interactive-accent, #79c0ff);\n  --manta-accent-text: var(--text-on-accent, #0d1117);\n  --manta-key-bg: #e6edf3;\n  --manta-key-text: #0d1117;\n  --manta-out-bg: #17293b;\n  --manta-out-border: #3b6ea5;\n  --manta-series-1: #9dc9a4;\n  --manta-series-2: #9cbfdf;\n  --manta-series-3: #dfc38a;\n  --manta-series-4: #c9a5d0;\n  --manta-error: var(--text-error, #ff7b72);\n  --manta-warning: var(--text-warning, #d29922);\n  --manta-success: var(--text-success, #3fb950);\n}\n\n@media (prefers-color-scheme: dark) {\n  :root:not(.theme-light):not([data-theme=\"light\"]) {\n    --manta-bg: var(--background-primary, #0d1117);\n    --manta-surface: var(--background-secondary, #161b22);\n    --manta-surface-raised: var(--background-secondary-alt, #1c2430);\n    --manta-border: var(--background-modifier-border, #3d4754);\n    --manta-border-strong: var(--background-modifier-border-hover, #738091);\n    --manta-divider: var(--divider-color, #2a323d);\n    --manta-text: var(--text-normal, #e6edf3);\n    --manta-text-muted: var(--text-muted, #a4afbc);\n    --manta-text-faint: var(--text-faint, #738091);\n    --manta-accent: var(--interactive-accent, #79c0ff);\n    --manta-accent-text: var(--text-on-accent, #0d1117);\n    --manta-key-bg: #e6edf3;\n    --manta-key-text: #0d1117;\n    --manta-out-bg: #17293b;\n    --manta-out-border: #3b6ea5;\n    --manta-series-1: #9dc9a4;\n    --manta-series-2: #9cbfdf;\n    --manta-series-3: #dfc38a;\n    --manta-series-4: #c9a5d0;\n    --manta-error: var(--text-error, #ff7b72);\n    --manta-warning: var(--text-warning, #d29922);\n    --manta-success: var(--text-success, #3fb950);\n}\n}\n\n/* 라이트를 고정한 호스트(인쇄·이력서 PDF)는 명시 선택자로 되돌린다. */\n.theme-light,\n[data-theme=\"light\"] {\n  --manta-bg: var(--background-primary, #ffffff);\n  --manta-surface: var(--background-secondary, #f4f6f8);\n  --manta-surface-raised: var(--background-secondary-alt, #eceff3);\n  --manta-border: var(--background-modifier-border, #c9cfd6);\n  --manta-border-strong: var(--background-modifier-border-hover, #8a929d);\n  --manta-divider: var(--divider-color, #e3e6ea);\n  --manta-text: var(--text-normal, #1f2328);\n  --manta-text-muted: var(--text-muted, #4b5563);\n  --manta-text-faint: var(--text-faint, #8a929d);\n  --manta-accent: var(--interactive-accent, #2b96ed);\n  --manta-accent-text: var(--text-on-accent, #ffffff);\n  --manta-key-bg: #1f2328;\n  --manta-key-text: #ffffff;\n  --manta-out-bg: #eaf3fc;\n  --manta-out-border: #9cc3e6;\n  --manta-series-1: #42764c;\n  --manta-series-2: #356eaa;\n  --manta-series-3: #896a28;\n  --manta-series-4: #81558d;\n  --manta-error: var(--text-error, #b42318);\n  --manta-warning: var(--text-warning, #b7791f);\n  --manta-success: var(--text-success, #176b35);\n}\n\n@media (forced-colors: active) {\n  :root,\n  .manta-tokens {\n  --manta-bg: Canvas;\n  --manta-surface: Canvas;\n  --manta-text: CanvasText;\n  --manta-border: CanvasText;\n  --manta-border-strong: CanvasText;\n}\n}\n\n/* md-* 는 manta 토큰의 별칭이다. 새 규칙은 --manta-* 를 직접 쓴다. */\n:root,\n.md-surface {\n  --md-paper: var(--manta-bg);\n  --md-ink: var(--manta-text);\n  --md-muted: var(--manta-text-muted);\n  --md-soft: var(--manta-text-faint);\n  --md-border: var(--manta-border);\n  --md-rule: var(--manta-divider);\n  --md-surface: var(--manta-surface);\n  --md-accent: var(--manta-accent);\n  --md-tint: var(--manta-out-bg);\n  --md-depth: var(--manta-divider);\n  --md-series1: var(--manta-series-1);\n  --md-series2: var(--manta-series-2);\n  --md-series3: var(--manta-series-3);\n  --md-series4: var(--manta-series-4);\n}\n/* tokens:end */\n";
